<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {knockoutRoundName,type TournamentSummary,type PlannedRound} from '@torneos/shared';
import Icon from './Icon.vue';
import SportTabs from './SportTabs.vue';
import SportEventMark from './SportEventMark.vue';
import TeamCrest from './TeamCrest.vue';
import BracketView from './BracketView.vue';

type FanEvent={id:string;kind:string;side:'home'|'away'|'unknown';period:string|null;minute:number|null;cardLabel:string|null;cardColor:string|null;name:string;relatedName:string|null};
type FanMatch={id:string;category_id:string;category_name:string;home_name:string;away_name:string;home_team_id:string;away_team_id:string;venue_name:string;court_label:string;match_date:string;match_time:string;tie_leg?:string|null;result:{status:'provisional'|'official';score:{home:number;away:number};shootout:{home:number;away:number};events:FanEvent[]}|null};
type FanDay={id:string;ordinal:number;tournament_id:string;matches:FanMatch[]};
type FanTeam={id:string;entry_id:string;name:string;color:string;has_shield:boolean;category_id:string};
type FanBracket={phase_id:string;category_id:string;repechage?:boolean;slots:Array<{stage:number;slot:number;home:string;away:string;twoLegs?:boolean;homeScore?:number|null;awayScore?:number|null;scoreLabel?:string|null;winnerSide?:'home'|'away'|null;resolution?:'aggregate'|'match_points_penalties'|'match_points_third';matchId?:string|null;matchIds?:{first:string|null;second:string|null;third:string|null};legs?:Array<{label:string;home:number;away:number;matchId?:string|null}>;shootout?:{home:number;away:number}|null}>};
type FanStats={available:boolean;phaseMode?:string|null;tables?:Array<{groupNo:number|null;rows:Array<{position:number;unresolved:boolean;teamName:string;played:number;wins:number;draws:number;losses:number;points:number;goalsFor:number;goalsAgainst:number;goalDifference:number}>}>;scorers?:Array<{name:string;teamName:string;goals:number}>;defense?:Array<{teamName:string;played:number;goalsAgainst:number}>;rosters?:Array<{entryId:string;players:Array<{name:string;goals:number;yellowCards:number;redCards:number}>}>};
type FanFlyer={id:string;kind:string;sourceId:string;tournamentId:string;title:string;format:string};
type CatalogItem={id:string;name:string;organization_id:string;organization_name:string};
const props=defineProps<{catalog:CatalogItem[];organization:{id:string;name:string;logo_id?:string|null}|null;selectedTournamentId:string;tournaments:TournamentSummary[];fixture:FanDay[];brackets:FanBracket[];statistics:Record<string,FanStats>;teams:FanTeam[];flyers:FanFlyer[];loading:boolean;error:string}>();
const emit=defineEmits<{navigate:[path:string]}>();
onMounted(()=>document.documentElement.classList.add('fan-scroll'));
onUnmounted(()=>document.documentElement.classList.remove('fan-scroll'));
const tab=ref('matches'),matchesView=ref<'days'|'bracket'>('days'),standingsView=ref<'league'|'bracket'>('league'),categoryId=ref(''),selectedMatch=ref<FanMatch|null>(null),selectedTeam=ref<FanTeam|null>(null),selectorOpen=ref(!props.selectedTournamentId),tournamentSearch=ref('');
const currentTournament=computed(()=>props.tournaments.find(item=>item.id===props.selectedTournamentId)||null);
const categories=computed(()=>props.tournaments.filter(item=>item.id===props.selectedTournamentId));
const category=computed(()=>categories.value.find(item=>item.category_id===categoryId.value)||categories.value[0]||null);
const currentCategoryId=computed(()=>category.value?.category_id||'');
const normalizeSearch=(value:string)=>value.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLocaleLowerCase('es');
const menuItems=computed(()=>props.catalog.filter(item=>(!props.organization||item.organization_id===props.organization.id)&&normalizeSearch(item.name).includes(normalizeSearch(tournamentSearch.value.trim()))));
const hasEmblem=(id:string)=>props.tournaments.some(item=>item.id===id&&item.has_emblem);
const emblemUrl=(organizationId:string,tournamentId:string)=>`/api/v1/public/organizations/${organizationId}/tournaments/${tournamentId}/emblem`;
const tabs=computed(()=>[
  {key:'matches',label:'Partidos',icon:'ball'},
  ...(category.value?.rules.initialPhase?.mode==='knockout'?[]:[{key:'standings',label:'Clasificación',icon:'chart'}]),
  {key:'scorers',label:'Goleadores',icon:'trophy'},
  {key:'defense',label:'Valla menos vencida',icon:'shield'},
  {key:'teams',label:'Equipos',icon:'users'},
]);
const stats=computed(()=>props.statistics[currentCategoryId.value]);
const days=computed(()=>props.fixture.map(day=>({...day,matches:day.matches.filter(match=>match.category_id===currentCategoryId.value)})).filter(day=>day.matches.length));
const bracket=computed(()=>props.brackets.find(item=>item.category_id===currentCategoryId.value));
const leagueBracket=computed(()=>category.value?.rules.initialPhase?.mode==='league'&&!!bracket.value);
const bracketRounds=computed<PlannedRound[]>(()=>[...new Set((bracket.value?.slots||[]).map(slot=>slot.stage))].map(stage=>{const ties=(bracket.value?.slots||[]).filter(slot=>slot.stage===stage).sort((a,b)=>a.slot-b.slot);const size=ties.length*2;return {size,name:stage===1&&bracket.value?.repechage?'Repechaje':knockoutRoundName(size),pairing:'positions' as const,legs:ties.some(tie=>tie.twoLegs)?2 as const:1 as const,ties};}));
const roundByMatchId=computed(()=>{const result=new Map<string,string>(),slots=bracket.value?.slots||[];for(const stage of new Set(slots.map(slot=>slot.stage))){const name=stage===1&&bracket.value?.repechage?'Repechaje':knockoutRoundName(slots.filter(slot=>slot.stage===stage).length*2);for(const slot of slots.filter(slot=>slot.stage===stage))for(const id of Object.values(slot.matchIds||{}))if(id)result.set(id,name);}return result;});
const categoryTeams=computed(()=>props.teams.filter(team=>team.category_id===currentCategoryId.value));
const defense=computed(()=>(stats.value?.defense||[]).filter(row=>row.played>0).sort((a,b)=>a.goalsAgainst-b.goalsAgainst||a.teamName.localeCompare(b.teamName,'es')));
const activeStatFlyer=computed(()=>tab.value==='standings'&&leagueBracket.value&&standingsView.value==='bracket'?flyer('bracket',bracket.value?.phase_id||''):['standings','scorers','defense'].includes(tab.value)?flyer(tab.value,currentCategoryId.value):undefined);
const roster=computed(()=>stats.value?.rosters?.find(item=>item.entryId===selectedTeam.value?.entry_id)?.players||[]);
const periods=[{code:'PT',label:'Primer tiempo'},{code:'ST',label:'Segundo tiempo'},{code:'TE',label:'Tiempo extra'},{code:'P4',label:'Cuarto tiempo'},{code:'P5',label:'Quinto tiempo'},{code:'P6',label:'Sexto tiempo'},{code:'',label:'Sin tiempo'}];
const eventGroups=computed(()=>periods.map(period=>{const events=(selectedMatch.value?.result?.events||[]).filter(event=>(event.period||'')===period.code);return {...period,label:period.code===''&&events.every(event=>event.kind.startsWith('shootout_'))?'Penales':period.label,events};}).filter(group=>group.events.length));
watch(()=>props.selectedTournamentId,id=>{tab.value='matches';matchesView.value='days';standingsView.value='league';categoryId.value='';selectedMatch.value=null;selectedTeam.value=null;selectorOpen.value=!id;tournamentSearch.value='';});
watch(category,()=>{selectedMatch.value=null;selectedTeam.value=null;standingsView.value='league';if(!tabs.value.some(item=>item.key===tab.value))tab.value='matches';});
let listScrollY=0;
watch([selectedMatch,selectedTeam],([match,team],[previousMatch,previousTeam])=>{if((match||team)&&!(previousMatch||previousTeam)){listScrollY=window.scrollY;void nextTick(()=>window.scrollTo(0,0));}else if(!match&&!team&&(previousMatch||previousTeam)){void nextTick(()=>window.scrollTo(0,listScrollY));}});
function chooseTournament(item:CatalogItem){selectorOpen.value=false;tournamentSearch.value='';emit('navigate',`publico/${item.organization_id}/${item.id}`);}
async function toggleSelector(){selectorOpen.value=!selectorOpen.value;if(selectorOpen.value){await nextTick();document.getElementById('fan-tournament-search')?.focus();}}
function team(id:string){return props.teams.find(item=>item.id===id&&item.category_id===currentCategoryId.value);}
function byName(name:string){return categoryTeams.value.find(item=>item.name===name);}
function eventLabel(event:FanEvent){return event.cardLabel||({goal:'Gol',penalty:'Penal',own_goal:'Autogol',yellow:'Amarilla',second_yellow:'Segunda amarilla',red:'Roja',custom_card:'Tarjeta',substitution:'Cambio',incident:'Incidencia',shootout_goal:'Penal convertido',shootout_miss:'Penal fallado'} as Record<string,string>)[event.kind]||'Evento';}
function shortDate(value:string){const [y,m,d]=value.split('-');return `${d}/${m}/${y}`;}
function dayTitle(day:FanDay){const names=[...new Set(day.matches.map(match=>roundByMatchId.value.get(match.id)))];if(names.length===1&&names[0]){const legs=[...new Set(day.matches.map(match=>match.tie_leg))];return legs.length===1&&legs[0]?`${names[0]} · ${legs[0]}`:names[0];}return names.length>1&&names.every(Boolean)?'Eliminación':`Fecha ${day.ordinal}`;}
function matchTitle(match:FanMatch){const day=days.value.find(item=>item.matches.some(entry=>entry.id===match.id));return `${roundByMatchId.value.get(match.id)||`Fecha ${day?.ordinal||''}`}${match.tie_leg?` · ${match.tie_leg}`:''}`;}
function openBracketMatch(id:string){const match=days.value.flatMap(day=>day.matches).find(item=>item.id===id);if(match)selectedMatch.value=match;}
function closeDetail(){selectedMatch.value=null;selectedTeam.value=null;}
function flyer(kind:string,sourceId:string){return props.flyers.find(item=>item.kind===kind&&item.sourceId===sourceId);}
function flyerUrl(item:FanFlyer){return `/api/v1/public/organizations/${props.organization?.id}/flyers/${item.id}/file`;}
</script>

<template>
  <div class="fan-ui">
    <header v-if="!selectedMatch&&!selectedTeam" class="fan-header"><div class="fan-header-inner"><span class="fan-overline"><img v-if="organization?.logo_id" class="fan-org-logo" :src="`/api/v1/public/organizations/${organization.id}/logo`" alt="">{{ organization?.name||'Torneos' }}</span><button id="fan-tournament" type="button" class="fan-selector-button" :aria-expanded="selectorOpen" aria-controls="fan-tournament-list" @click="toggleSelector"><img v-if="currentTournament?.has_emblem && organization" class="fan-emblem" :src="emblemUrl(organization.id,currentTournament.id)" alt=""><Icon v-else name="trophy" /><strong>{{ currentTournament?.name||'Elegí un torneo' }}</strong><Icon name="chevron" :class="{'is-open':selectorOpen}" /></button></div></header>
    <nav v-if="!selectedMatch&&!selectedTeam" v-show="selectorOpen" id="fan-tournament-list" class="fan-tournament-list" aria-label="Torneos" @keydown.esc="selectorOpen=false"><label class="fan-tournament-search"><Icon name="search" /><input id="fan-tournament-search" v-model="tournamentSearch" type="search" placeholder="Buscar torneo" aria-label="Buscar torneo" autocomplete="off"></label><button v-for="item in menuItems" :key="`${item.organization_id}-${item.id}`" type="button" :aria-current="selectedTournamentId===item.id?'page':undefined" @click="chooseTournament(item)"><img v-if="hasEmblem(item.id)" class="fan-emblem" :src="emblemUrl(item.organization_id,item.id)" alt=""><Icon v-else name="trophy" /><span><strong>{{ item.name }}</strong><small v-if="!organization">{{ item.organization_name }}</small></span><Icon :name="selectedTournamentId===item.id?'check':'arrow'" /></button><p v-if="!loading&&!menuItems.length" class="fan-empty">{{ tournamentSearch ? 'Sin resultados.' : 'Aún no hay torneos publicados.' }}</p></nav>
    <div v-if="loading" class="fan-status" role="status">Cargando…</div>
    <div v-if="error" class="fan-status error" role="alert">{{ error }}</div>
    <template v-if="currentTournament&&!loading&&!error">
      <div class="fan-category" v-if="categories.length>1" role="group" aria-label="Categoría"><button v-for="item in categories" :key="item.category_id" type="button" :aria-pressed="currentCategoryId===item.category_id" @click="categoryId=item.category_id">{{ item.category_name }}</button></div>
      <template v-if="selectedMatch">
        <div class="fan-detail-top"><button type="button" class="fan-close" aria-label="Cerrar partido" @click="closeDetail"><Icon name="close" /></button><span>{{ matchTitle(selectedMatch) }}</span><a v-if="flyer('result',selectedMatch.id)||flyer('match',selectedMatch.id)" class="fan-flyer-link" :href="flyerUrl(flyer('result',selectedMatch.id)||flyer('match',selectedMatch.id)!)" target="_blank" rel="noopener"><Icon name="download" /> Flyer</a></div>
        <section class="fan-scoreboard" aria-label="Resultado del partido"><p class="fan-match-state">{{ selectedMatch.result?.status==='official'?'FINAL':selectedMatch.result?.status==='provisional'?'PROVISIONAL':shortDate(selectedMatch.match_date)+' · '+selectedMatch.match_time }}</p><div class="fan-score-grid"><div class="fan-score-team"><TeamCrest size="lg" :name="selectedMatch.home_name" :team-id="selectedMatch.home_team_id" :organization-id="organization?.id" :color="team(selectedMatch.home_team_id)?.color" :has-shield="team(selectedMatch.home_team_id)?.has_shield" /><strong :title="selectedMatch.home_name">{{ selectedMatch.home_name }}</strong></div><div class="fan-score-number">{{ selectedMatch.result?`${selectedMatch.result.score.home} : ${selectedMatch.result.score.away}`:'—' }}</div><div class="fan-score-team"><TeamCrest size="lg" :name="selectedMatch.away_name" :team-id="selectedMatch.away_team_id" :organization-id="organization?.id" :color="team(selectedMatch.away_team_id)?.color" :has-shield="team(selectedMatch.away_team_id)?.has_shield" /><strong :title="selectedMatch.away_name">{{ selectedMatch.away_name }}</strong></div></div><p class="fan-score-meta">{{ shortDate(selectedMatch.match_date) }} · {{ selectedMatch.match_time }}<template v-if="selectedMatch.venue_name"> · {{ selectedMatch.venue_name }}</template></p><p v-if="selectedMatch.result&&(selectedMatch.result.shootout.home||selectedMatch.result.shootout.away)" class="fan-score-meta">Penales {{ selectedMatch.result.shootout.home }} : {{ selectedMatch.result.shootout.away }}</p></section>
        <div class="fan-content"><h2 class="fan-section-label">Eventos</h2><p v-if="!eventGroups.length" class="fan-empty">Aún sin eventos públicos.</p><section v-for="group in eventGroups" :key="group.code" class="fan-period"><h3>{{ group.label }}</h3><div v-for="event in group.events" :key="event.id" class="fan-event" :class="`is-${event.side}`"><div class="fan-event-side"><SportEventMark :kind="event.kind" :color="event.cardColor||undefined" /><span><strong :title="event.name">{{ event.name }}</strong><small>{{ eventLabel(event) }}<template v-if="event.relatedName"> · {{ event.relatedName }}</template></small></span></div><span class="fan-event-minute">{{ event.minute===null?'':`${event.minute}′` }}</span></div></section></div>
      </template>
      <template v-else-if="selectedTeam">
        <div class="fan-detail-top"><button type="button" class="fan-close" aria-label="Cerrar equipo" @click="closeDetail"><Icon name="close" /></button><span>Equipo</span></div><div class="fan-team-hero"><TeamCrest size="lg" :name="selectedTeam.name" :team-id="selectedTeam.id" :organization-id="organization?.id" :color="selectedTeam.color" :has-shield="selectedTeam.has_shield" /><h1 :title="selectedTeam.name">{{ selectedTeam.name }}</h1></div><div class="fan-content"><div class="fan-roster-head"><h2>Jugadores</h2><span>Goles · Tarjetas</span></div><p v-if="!roster.length" class="fan-empty">Aún no hay jugadores publicados.</p><div v-for="player in roster" :key="player.name" class="fan-player-row"><strong :title="player.name">{{ player.name }}</strong><span class="fan-player-stat"><Icon name="ball" />{{ player.goals }}</span><span class="fan-player-stat"><i class="fan-small-card yellow"></i>{{ player.yellowCards }}</span><span class="fan-player-stat"><i class="fan-small-card red"></i>{{ player.redCards }}</span></div></div>
      </template>
      <template v-else>
        <div class="fan-tabs-wrap"><SportTabs v-model="tab" :tabs="tabs" id="fan-sections" /></div>
        <section v-if="tab==='matches'" id="fan-sections-matches-panel" role="tabpanel" aria-labelledby="fan-sections-matches-tab" class="fan-content">
          <div v-if="bracket" class="fan-subtabs" role="group" aria-label="Vista de partidos"><button type="button" :aria-pressed="matchesView==='days'" @click="matchesView='days'">Fechas</button><button type="button" :aria-pressed="matchesView==='bracket'" @click="matchesView='bracket'">Cuadro</button></div>
          <template v-if="matchesView==='days'">
            <p v-if="!days.length" class="fan-empty">Aún no hay partidos publicados.</p>
            <section v-for="day in days" :key="day.id" class="fan-day">
              <div class="fan-day-head"><h2>{{ dayTitle(day) }}</h2><a v-if="flyer('matchday',day.id)" class="fan-flyer-link" :href="flyerUrl(flyer('matchday',day.id)!)" target="_blank" rel="noopener"><Icon name="download" /> Flyer</a></div>
              <button v-for="match in day.matches" :key="match.id" type="button" class="fan-match-row" :aria-label="`${match.home_name} contra ${match.away_name}, ${match.result?`${match.result.score.home} a ${match.result.score.away}`:match.match_time}. Ver partido`" @click="selectedMatch=match">
                <span class="fan-match-date">{{ match.result?.status==='official'?'Final':match.match_time }}<small v-if="match.tie_leg">{{ match.tie_leg }}</small></span>
                <span class="fan-match-team"><TeamCrest size="sm" :name="match.home_name" :team-id="match.home_team_id" :organization-id="organization?.id" :color="team(match.home_team_id)?.color" :has-shield="team(match.home_team_id)?.has_shield" /><strong :title="match.home_name">{{ match.home_name }}</strong></span>
                <span class="fan-match-result"><b>{{ match.result?`${match.result.score.home} : ${match.result.score.away}`:'vs' }}</b><small v-if="match.result&&(match.result.shootout.home||match.result.shootout.away)">Pen. {{ match.result.shootout.home }}:{{ match.result.shootout.away }}</small></span>
                <span class="fan-match-team"><TeamCrest size="sm" :name="match.away_name" :team-id="match.away_team_id" :organization-id="organization?.id" :color="team(match.away_team_id)?.color" :has-shield="team(match.away_team_id)?.has_shield" /><strong :title="match.away_name">{{ match.away_name }}</strong></span><Icon name="arrow" />
              </button>
            </section>
          </template>
          <template v-else><div v-if="flyer('bracket',bracket?.phase_id||'')" class="fan-context-action"><a class="fan-flyer-link" :href="flyerUrl(flyer('bracket',bracket?.phase_id||'')!)" target="_blank" rel="noopener"><Icon name="download" /> Flyer</a></div><BracketView :rounds="bracketRounds" :teams="categoryTeams" :organization-id="organization?.id" @open-match="openBracketMatch" /></template>
        </section>
        <div v-if="activeStatFlyer" class="fan-context-action fan-context-outside"><a class="fan-flyer-link" :href="flyerUrl(activeStatFlyer)" target="_blank" rel="noopener"><Icon name="download" /> Flyer</a></div>
        <section v-if="tab==='standings'" id="fan-sections-standings-panel" role="tabpanel" aria-labelledby="fan-sections-standings-tab" class="fan-content">
          <div v-if="leagueBracket" class="fan-subtabs" role="group" aria-label="Fases de clasificación"><button type="button" :aria-pressed="standingsView==='league'" @click="standingsView='league'">Liguilla</button><button type="button" :aria-pressed="standingsView==='bracket'" @click="standingsView='bracket'">Eliminación</button></div>
          <template v-if="!leagueBracket||standingsView==='league'">
            <p v-if="!stats?.available" class="fan-empty">Aún sin clasificación publicada.</p>
            <div v-for="table in stats?.tables||[]" :key="String(table.groupNo)" class="fan-table"><h2 v-if="table.groupNo!==null">Grupo {{ table.groupNo }}</h2><div class="fan-table-head"><span>Equipo</span><span>PJ</span><span>DG</span><span>Pts</span></div><div v-for="row in table.rows" :key="row.teamName" class="fan-table-row"><span class="fan-rank">{{ row.unresolved?'—':row.position }}</span><TeamCrest size="sm" :name="row.teamName" :team-id="byName(row.teamName)?.id" :organization-id="organization?.id" :color="byName(row.teamName)?.color" :has-shield="byName(row.teamName)?.has_shield" /><strong :title="row.teamName">{{ row.teamName }}</strong><span>{{ row.played }}</span><span>{{ row.goalDifference }}</span><b>{{ row.points }}</b></div></div>
          </template>
          <BracketView v-else :rounds="bracketRounds" :teams="categoryTeams" :organization-id="organization?.id" @open-match="openBracketMatch" />
        </section>
        <section v-if="tab==='scorers'" id="fan-sections-scorers-panel" role="tabpanel" aria-labelledby="fan-sections-scorers-tab" class="fan-content"><p v-if="!stats?.scorers?.length" class="fan-empty">Aún no hay goleadores publicados.</p><div v-for="(player,index) in stats?.scorers||[]" :key="`${player.name}-${index}`" class="fan-scorer-row"><span class="fan-rank">{{ index+1 }}</span><TeamCrest size="sm" :name="player.teamName" :team-id="byName(player.teamName)?.id" :organization-id="organization?.id" :color="byName(player.teamName)?.color" :has-shield="byName(player.teamName)?.has_shield" /><span><strong :title="player.name">{{ player.name }}</strong><small :title="player.teamName">{{ player.teamName }}</small></span><b>{{ player.goals }}</b></div></section>
        <section v-if="tab==='defense'" id="fan-sections-defense-panel" role="tabpanel" aria-labelledby="fan-sections-defense-tab" class="fan-content"><p v-if="!defense.length" class="fan-empty">Aún no hay partidos oficiales.</p><div v-else class="fan-defense-head"><span>Equipo</span><span>PJ</span><span>GC</span></div><div v-for="(row,index) in defense" :key="row.teamName" class="fan-defense-row"><span class="fan-rank">{{ index+1 }}</span><TeamCrest size="sm" :name="row.teamName" :team-id="byName(row.teamName)?.id" :organization-id="organization?.id" :color="byName(row.teamName)?.color" :has-shield="byName(row.teamName)?.has_shield" /><strong :title="row.teamName">{{ row.teamName }}</strong><span>{{ row.played }}</span><b>{{ row.goalsAgainst }}</b></div></section>
        <section v-if="tab==='teams'" id="fan-sections-teams-panel" role="tabpanel" aria-labelledby="fan-sections-teams-tab" class="fan-content"><p v-if="!categoryTeams.length" class="fan-empty">Aún no hay equipos publicados.</p><button v-for="item in categoryTeams" :key="item.entry_id" type="button" class="fan-team-row" @click="selectedTeam=item"><TeamCrest :name="item.name" :team-id="item.id" :organization-id="organization?.id" :color="item.color" :has-shield="item.has_shield" /><strong :title="item.name">{{ item.name }}</strong><Icon name="arrow" /></button></section>
      </template>
    </template>
  </div>
